<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import {companyHasCapability} from '../../../shared/company-formats.js';
import {api} from '../services/accounting.js';
import {downloadFile} from '../services/documentation.js';
import {farmCategories,farmQuantity,farmProductionError as farmError,previewFarmPdf} from '../services/farms.js';
import FormDialog from '../components/FormDialog.vue';
import FarmLotForm from '../components/FarmLotForm.vue';
import FarmSales from '../components/FarmSales.vue';
import FarmProduction from '../components/FarmProduction.vue';
import FarmProductionEventForm from '../components/FarmProductionEventForm.vue';
import FarmReportDialog from '../components/FarmReportDialog.vue';
import FarmExpenseDetail from '../components/FarmExpenseDetail.vue';
import {scaled,fixed} from '../../../shared/farm-costs.js';
const {company,selectedId}=useContext(),{can}=useAccess();
const enabled=computed(()=>companyHasCapability(company.value,'pig_production'));
const data=ref(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const farm=ref(''),lot=ref(''),category=ref(''),from=ref(''),to=ref(''),search=ref(''),farmSearch=ref(''),page=ref(1);
const preview=ref(null),edit=ref(null),farmForm=ref(null),lotForm=ref(null),dialogError=ref('');let generation=0;
const reportOpen=ref(false),eventForm=ref(null);
const categoryDetail=ref(null);let detailSequence=0;
watch([()=>company.value?.id,selectedId,farm,lot],()=>{categoryDetail.value=null;detailSequence++;});
watch([()=>company.value?.id,selectedId],()=>{reportOpen.value=false;eventForm.value=null;});
const money=value=>Number(value||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
const date=value=>value?value.split('-').reverse().join('/'):'—';
const currentFarm=computed(()=>data.value?.farms.find(row=>String(row.id)===farm.value));
const farmLots=computed(()=>(data.value?.lots||[]).filter(row=>String(row.farm_id)===farm.value));
const editLots=computed(()=>(data.value?.lots||[]).filter(row=>String(row.farm_id)===edit.value?.farm_id));
const selectedLot=computed(()=>{const row=data.value?.selected_lot;return row&&String(row.id)===lot.value&&String(row.farm_id)===farm.value?row:null;});
const totalCost=computed(()=>selectedLot.value?data.value.sales_totals.cost:data.value?.totals.base||'0.00');
const scopeVat=computed(()=>selectedLot.value?data.value.scope_totals?.vat||data.value.totals.vat:data.value?.totals.vat||'0.00');
const totalWithVat=computed(()=>fixed(scaled(totalCost.value,2)+scaled(scopeVat.value,2),2));
const farms=computed(()=>{const needle=farmSearch.value.trim().toLocaleLowerCase('es');return(data.value?.farms||[]).filter(row=>!needle||(row.code+' '+row.name).toLocaleLowerCase('es').includes(needle));});
const query=()=>new URLSearchParams(Object.entries({exercise_id:lot.value&&lot.value!=='pending'?'all':selectedId.value||'all',farm_id:farm.value,lot_id:lot.value,category:category.value,from:from.value,to:to.value}).filter(([,value])=>value));
async function load(){const ticket=++generation;if(!enabled.value){data.value=null;loading.value=false;return;}loading.value=true;error.value='';try{const result=await api('/farms?'+query(),{timeoutMs:30000});if(ticket===generation)data.value=result;}catch(cause){if(ticket===generation)error.value=farmError(cause);}finally{if(ticket===generation)loading.value=false;}}
const lines=computed(()=>{const needle=search.value.trim().toLocaleLowerCase('es');return(data.value?.lines||[]).filter(row=>!needle||[row.reference,row.description,row.notes,row.farm_name,row.lot_code,row.product_code,row.delivery_reference,row.base_amount].some(value=>String(value||'').toLocaleLowerCase('es').includes(needle)));});
const pages=computed(()=>Math.max(1,Math.ceil(lines.value.length/50))),visible=computed(()=>lines.value.slice((page.value-1)*50,page.value*50));
const maxMonth=computed(()=>Math.max(1,...(data.value?.months||[]).map(row=>Math.abs(Number(row.base)))));
watch([search,farm,lot,category,from,to],()=>page.value=1);watch(pages,value=>page.value=Math.min(page.value,value));
watch([()=>company.value?.id,selectedId,enabled],()=>{data.value=null;farm.value='';lot.value='';category.value='';from.value='';to.value='';search.value='';farmSearch.value='';preview.value=null;edit.value=null;farmForm.value=null;lotForm.value=null;notice.value='';void load();},{immediate:true});
onBeforeUnmount(()=>{generation++;if(preview.value)void api('/farms/discard',{method:'POST',body:{token:preview.value.token}}).catch(()=>{});});
function preferredLot(value){const options=(data.value?.lots||[]).filter(row=>String(row.farm_id)===value);return options.find(row=>!row.exit_date)||options[0]||null;}
function selectFarm(value){const preferred=preferredLot(value);farm.value=value;lot.value=value&&value!=='pending'?(preferred?String(preferred.id):'pending'):'';from.value='';to.value='';category.value='';search.value='';data.value=null;void load();}
function selectLot(value){lot.value=value;from.value='';to.value='';category.value='';search.value='';data.value=null;void load();}
function selectCurrentLot(){const row=preferredLot(farm.value);selectLot(row?String(row.id):'pending');}
async function openCategory(key){const ticket=++detailSequence,params=query();params.set('category',key);categoryDetail.value={ticket,key,loading:true,error:'',data:null,scope:selectedLot.value?'Lote '+selectedLot.value.code+' · '+currentFarm.value.name:currentFarm.value?.name||company.value.name};try{const result=await api('/farms?'+params,{timeoutMs:30000});if(categoryDetail.value?.ticket===ticket)categoryDetail.value.data=result;}catch(cause){if(categoryDetail.value?.ticket===ticket)categoryDetail.value.error=farmError(cause);}finally{if(categoryDetail.value?.ticket===ticket)categoryDetail.value.loading=false;}}
function monthFilter(month){from.value=month+'-01';const [year,number]=month.split('-').map(Number);to.value=month+'-'+new Date(Date.UTC(year,number,0)).getUTCDate();void load();}
function clearFilters(){category.value='';from.value='';to.value='';search.value='';void load();}
async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file||busy.value)return;const companyId=company.value?.id,exerciseId=selectedId.value;busy.value=true;error.value='';dialogError.value='';try{const result=await previewFarmPdf(file,exerciseId);if(companyId===company.value?.id&&exerciseId===selectedId.value)preview.value=result;}catch(cause){error.value=farmError(cause);}finally{busy.value=false;}}
async function closePreview(){if(busy.value)return;const token=preview.value?.token;preview.value=null;dialogError.value='';if(token)await api('/farms/discard',{method:'POST',body:{token}}).catch(()=>{});}
async function commit(){if(busy.value||!preview.value?.ready)return;busy.value=true;dialogError.value='';try{const result=await api('/farms/import',{method:'POST',timeoutMs:120000,body:{token:preview.value.token}});void api('/farms/discard',{method:'POST',body:{token:preview.value.token}}).catch(()=>{});preview.value=null;notice.value=result.imported+' facturas incorporadas.';await load();}catch(cause){dialogError.value=farmError(cause);}finally{busy.value=false;}}
function editCost(row){categoryDetail.value=null;if(row.source_kind==='care'){eventForm.value={kind:'care',event:row};return;}dialogError.value='';edit.value={...row,feed_kg:row.feed_kg??'',farm_id:row.farm_id===null?'':String(row.farm_id),lot_selection:row.lot_assignment==='manual'?String(row.lot_id):row.lot_assignment||'auto'};}
async function saveCost(){busy.value=true;dialogError.value='';try{const choice=edit.value.lot_selection;await api('/farms/costs/'+edit.value.id,{method:'PATCH',body:{farm_id:edit.value.farm_id?Number(edit.value.farm_id):null,category:edit.value.category,version:edit.value.version,feed_kg:edit.value.feed_kg===''?null:edit.value.feed_kg,lot_assignment:['auto','unassigned'].includes(choice)?choice:'manual',lot_id:['auto','unassigned'].includes(choice)?null:Number(choice)}});edit.value=null;await load();}catch(cause){dialogError.value=farmError(cause);}finally{busy.value=false;}}
function openFarm(row){dialogError.value='';farmForm.value=row?{...row}:{code:'',name:'',notes:''};}
async function saveFarm(){busy.value=true;dialogError.value='';try{const form=farmForm.value,result=await api('/farms'+(form.id?'/'+form.id:''),{method:form.id?'PATCH':'POST',body:form});farmForm.value=null;if(!form.id){farm.value=String(result.id);lot.value='';}await load();}catch(cause){dialogError.value=farmError(cause);}finally{busy.value=false;}}
async function lotSaved(result){lotForm.value=null;notice.value='Lote guardado. Los costes de cada ciclo se consultan por separado.';selectLot(String(result.id));}
async function productionSaved(result){eventForm.value=null;notice.value='Registro guardado. El informe del lote está actualizado.';if(result?.lot_id){const row=data.value?.lots.find(item=>item.id===result.lot_id);if(row){farm.value=String(row.farm_id);lot.value=String(row.id);from.value='';to.value='';category.value='';}}data.value=null;await load();}
async function source(row){error.value='';try{await downloadFile('/farms/documents/'+(row.document_id||row.id)+'/source',row.source_name||'facturas-originales.pdf');}catch(cause){error.value=farmError(cause);}}
function csv(){const quote=value=>'"'+String(value??'').replace(/"/g,'""')+'"';const rows=[['Fecha','Factura','Granja','Lote','Concepto','Unidades','Categoría','Base','IVA','Total','Página'],...lines.value.map(row=>[row.invoice_date,row.reference,row.farm_name||'Pendiente de asignar',row.lot_code||'Sin lote',row.description,row.quantity,farmCategories[row.category],row.base_amount,row.vat_amount,row.total_amount,row.source_page])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(row=>row.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='costes-granjas.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template>
 <div class="page-heading"><div><h1>Gestión de granjas</h1><p class="muted">{{ company?.name }}</p></div><div v-if="enabled" class="actions"><button class="button" :disabled="!can('accounting_write')||busy" @click="openFarm()">Nueva granja</button><label class="button primary farm-upload">{{ busy?'Procesando…':'Importar gastos del PDF' }}<input type="file" accept="application/pdf,.pdf" :disabled="busy||!can('data_import')||!selectedId" @change="upload"></label></div></div>
 <p v-if="!enabled" class="notice">Disponible para empresas con formato «Producción porcina» en su ficha.</p>
 <template v-else>
  <p v-if="error" role="alert" class="notice error-notice">{{ error }}</p><p v-if="notice" role="status" class="success-note">{{ notice }}</p><p v-if="loading||busy" role="status" class="muted">{{ loading?'Cargando costes…':'Procesando…' }}</p>
  <div v-if="farm" class="farm-breadcrumb"><button class="farm-row-link" @click="selectFarm('')">Todas las granjas</button><span>/</span><strong>{{ currentFarm?.name||'Pendiente de asignar' }}</strong><template v-if="selectedLot"><span>/</span><span>Lote {{ selectedLot.code }}</span></template></div>
  <template v-if="data">
   <section class="panel farm-quick-actions" aria-label="Acciones del lote"><template v-if="currentFarm"><div><strong>{{ currentFarm.name }}</strong><label for="active-farm-lot">Lote seleccionado<select id="active-farm-lot" :value="lot" :disabled="loading" @change="selectLot($event.target.value)"><option v-if="!farmLots.length" value="pending">Sin lote: crea el primero</option><option v-for="row in farmLots" :key="row.id" :value="String(row.id)">{{ row.code }} · {{ row.exit_date?'cerrado':'abierto' }}</option><option v-if="farmLots.length" value="pending">Gastos sin lote</option></select></label></div></template><p v-else class="muted">Elige una granja para consultar el lote actual.</p><div class="actions"><button class="button primary" :disabled="!can('accounting_write')||!data.lots.length||loading" @click="eventForm={kind:'death',event:null}">Registrar bajas</button><button class="button" :disabled="!can('accounting_write')||!data.lots.length||loading" @click="eventForm={kind:'care',event:null}">Registrar cuido</button></div></section>
   <div class="farm-charts" :aria-busy="loading">
    <section class="panel farm-section farm-evolution"><h2>Evolución mensual</h2><p class="muted">Coste sin IVA · {{ selectedLot?'Ciclo completo del lote':data.exercise?.name||'Todos los ejercicios' }}</p><div v-for="month in data.months" :key="month.month" class="farm-month"><button class="farm-row-link" :aria-label="'Ver gastos de '+month.month" @click="monthFilter(month.month)">{{ month.month }}</button><meter :value="Math.abs(Number(month.base))" :max="maxMonth" :aria-label="month.month+' '+money(month.base)"></meter><strong>{{ money(month.base) }}</strong></div><p v-if="!data.months.length" class="farm-chart-empty muted">Sin gastos en este período.</p></section>
    <section class="panel farm-section farm-types"><h2>Tipos de gasto</h2><p class="muted">Pulsa un tipo para abrir su detalle.</p><dl class="farm-categories"><template v-for="row in data.categories" :key="row.category"><dt><button class="farm-row-link" @click="openCategory(row.category)">{{ farmCategories[row.category] }}</button></dt><dd><button class="farm-row-link farm-amount-link" :aria-label="'Ver detalle de '+farmCategories[row.category]" @click="openCategory(row.category)">{{ money(row.base) }}</button></dd></template></dl></section>
   </div>
   <form class="filters farm-filters" @submit.prevent="load"><label for="farm-category">Tipo de gasto<select id="farm-category" v-model="category"><option value="">Todos los tipos</option><option v-for="(label,key) in farmCategories" :key="key" :value="key">{{ label }}</option></select></label><label for="farm-from">Desde<input id="farm-from" v-model="from" type="date"></label><label for="farm-to">Hasta<input id="farm-to" v-model="to" type="date"></label><button class="button" :disabled="loading">Aplicar filtros</button><button v-if="category||from||to" type="button" class="button" @click="clearFilters">Quitar filtros</button></form>
   <div class="farm-totals"><div><small>{{ selectedLot?'Gastos del lote '+selectedLot.code+' (sin IVA)':lot==='pending'?'Gastos sin lote':'Coste sin IVA' }}</small><strong>{{ money(totalCost) }}</strong></div><div><small>IVA de facturas</small><strong>{{ money(scopeVat) }}</strong></div><div><small>Gastos con IVA</small><strong>{{ money(totalWithVat) }}</strong></div><button v-if="!farm||farm==='pending'" class="farm-pending" @click="selectFarm('pending')"><small>Sin granja</small><strong>{{ money(data.pending.base) }}</strong></button></div>
   <div class="actions farm-export"><button class="button primary" :disabled="busy||!data.lots.length" @click="reportOpen=true">Informe de granja y lote</button><button class="button" :disabled="busy||!can('accounting_write')||!data.lots.length" @click="eventForm={kind:'transfer',event:null}">Traspasar pienso</button><button class="button" :disabled="!lines.length" @click="csv">Exportar CSV</button><span class="muted">{{ data.totals.invoices }} facturas · {{ data.totals.lines }} líneas</span></div>
   <section v-if="!farm" class="panel farm-section farm-directory"><div class="farm-section-heading"><div><h2>Granjas</h2><p class="muted">Abre una granja para consultar sus lotes y gastos.</p></div><label for="farm-search">Buscar granja<input id="farm-search" v-model="farmSearch" type="search" placeholder="Nombre o código"></label></div><div class="farm-grid"><button v-for="row in farms" :key="row.id" class="farm-card" @click="selectFarm(String(row.id))"><span class="farm-code">{{ row.code }}</span><strong>{{ row.name }}</strong><span aria-hidden="true">›</span></button></div><p v-if="!farms.length" class="muted">{{ farmSearch?'No hay granjas con ese nombre.':'Importa el PDF o añade una granja para empezar.' }}</p></section>
   <template v-else>
    <section v-if="currentFarm" class="panel farm-section farm-lots">
     <div class="farm-section-heading"><div><h2>{{ currentFarm.name }}</h2><p class="muted">Consulta el lote seleccionado o abre otro ciclo.</p></div><div class="actions"><button class="button" :disabled="!can('accounting_write')" @click="openFarm(currentFarm)">Editar ficha</button><button class="button primary" :disabled="!can('accounting_write')" @click="lotForm={lot:null,closing:false}">Nuevo lote</button></div></div>
     <p v-if="currentFarm.notes" class="muted">{{ currentFarm.notes }}</p><div class="farm-lot-list"><article v-for="row in farmLots" :key="row.id" class="farm-lot-card" :class="{selected:lot===String(row.id)}"><button class="farm-lot-open" @click="selectLot(String(row.id))"><strong>Lote {{ row.code }}</strong><span class="badge" :class="row.exit_date?'badge-closed':'badge-open'">{{ row.exit_date?'Cerrado':'Abierto' }}</span><small>Entrada {{ date(row.entry_date) }} · {{ row.exit_date?'Salida '+date(row.exit_date):'Animales en la granja' }}</small><small v-if="row.animals_in!==null">{{ row.animals_in }} animales de entrada<span v-if="row.animals_out!==null"> · {{ row.animals_out }} de salida</span></small></button><div class="actions"><button v-if="!row.exit_date" class="button" :disabled="!can('accounting_write')" @click="lotForm={lot:row,closing:true}">Cerrar lote</button><button class="button" :disabled="!can('accounting_write')" @click="lotForm={lot:row,closing:false}">Editar lote</button></div></article></div>
     <p v-if="!farmLots.length" class="notice">Esta granja todavía no tiene lotes. Pulsa «Nuevo lote» para registrar el primero.</p><div class="actions farm-lot-filters"><button class="button" @click="selectCurrentLot">Volver al lote actual</button><button class="button" :class="{primary:lot==='pending'}" @click="selectLot('pending')">Gastos sin lote</button></div><p class="muted">Los totales corresponden al lote seleccionado. Los gastos sin lote se consultan por separado.</p>
    </section>
    <FarmSales v-if="currentFarm" :lot="selectedLot" :lots="farmLots" :sales="data.sales" :summary="data.sales_totals" @changed="load" />
    <FarmProduction v-if="selectedLot" :lot="selectedLot" :production="data.production" :deaths="data.deaths" :transfers="data.transfers" @edit="eventForm=$event" />
    <section class="panel farm-section farm-expenses"><h2>{{ selectedLot?'Gastos del lote '+selectedLot.code:lot==='pending'?'Gastos sin lote':farm==='pending'?'Gastos sin granja':'Gastos de la granja' }}</h2><p v-if="selectedLot" class="muted">Ciclo completo: {{ date(selectedLot.entry_date) }} — {{ selectedLot.exit_date?date(selectedLot.exit_date):'abierto' }} · incluye todos los ejercicios.</p><label for="cost-search">Buscar gasto<input id="cost-search" v-model="search" type="search" placeholder="Factura, concepto, lote, albarán o importe"></label><div class="table-wrap"><table><thead><tr><th>Fecha / documento</th><th>Concepto</th><th>Lote</th><th>Tipo</th><th class="number">Unidades</th><th class="number">Base</th><th class="number">IVA</th><th class="number">Total</th></tr></thead><tbody><tr v-for="row in visible" :key="(row.source_kind||'invoice')+'-'+row.id" class="farm-click-row" @click="editCost(row)"><td><button class="farm-row-link" @click.stop="editCost(row)">{{ row.reference }}</button><small class="trade-cell-note">{{ date(row.invoice_date) }}<span v-if="row.source_page"> · pág. {{ row.source_page }}</span></small></td><td>{{ row.description }}<small v-if="row.informational" class="trade-cell-note">Línea informativa sin importe</small></td><td>{{ row.lot_code||'Sin lote' }}<small v-if="row.lot_reason==='ambiguous_date'" class="trade-cell-note">Cambio de lote ese día</small></td><td>{{ farmCategories[row.category] }}</td><td class="number">{{ farmQuantity(row.quantity) }}</td><td class="number">{{ money(row.base_amount) }}</td><td class="number">{{ money(row.vat_amount) }}</td><td class="number">{{ money(row.total_amount) }}</td></tr><tr v-if="!lines.length"><td colspan="8" class="empty-cell">No hay gastos con estos filtros.</td></tr></tbody></table></div><div class="actions farm-pagination"><button class="button" :disabled="page<=1" @click="page--">Anterior</button><span>Página {{ page }} de {{ pages }} · {{ lines.length }} líneas</span><button class="button" :disabled="page>=pages" @click="page++">Siguiente</button></div></section>
   </template>
   <details class="farm-documents"><summary>Documentos originales ({{ data.documents.length }})</summary><ul><li v-for="doc in data.documents" :key="doc.id"><button class="farm-row-link" @click="source(doc)">{{ doc.source_name }}</button> · {{ doc.page_count }} páginas</li></ul></details>
  </template>
 </template>
 <FarmReportDialog v-if="reportOpen&&data" :farms="data.farms" :lots="data.lots" :farm-id="currentFarm?String(currentFarm.id):''" :lot-id="selectedLot?String(selectedLot.id):''" @close="reportOpen=false" />
 <FarmProductionEventForm v-if="eventForm&&data" :kind="eventForm.kind" :event="eventForm.event" :lot="selectedLot" :farms="data.farms" :lots="data.lots" @close="eventForm=null" @saved="productionSaved" />
 <FarmExpenseDetail v-if="categoryDetail" :label="farmCategories[categoryDetail.key]" :scope="categoryDetail.scope" :data="categoryDetail.data" :loading="categoryDetail.loading" :error="categoryDetail.error" :can-edit="can('accounting_write')" :care="categoryDetail.key==='care'" @close="categoryDetail=null" @edit="editCost" @care="categoryDetail=null;eventForm={kind:'care',event:null}" />
 <FarmLotForm v-if="lotForm&&currentFarm" :farm="currentFarm" :lot="lotForm.lot" :lots="farmLots" :closing="lotForm.closing" @close="lotForm=null" @saved="lotSaved" />
 <FormDialog v-if="preview" title="Revisar costes del PDF" :busy="busy" @close="closePreview"><p>{{ preview.company_name }} · {{ preview.exercise_name }} · {{ preview.pages }} páginas</p><p><strong>{{ preview.totals.invoices }} facturas nuevas · {{ money(preview.totals.base) }} sin IVA</strong><br>IVA: {{ money(preview.totals.vat) }} · Total: {{ money(preview.totals.total) }}</p><p v-if="preview.duplicates.length">{{ preview.duplicates.length }} facturas ya registradas; no se volverán a incorporar.</p><p v-if="preview.conflicts.length" class="notice error-notice">Referencias existentes con otro contenido: {{ preview.conflicts.join(', ') }}.</p><p>{{ preview.farms.length }} granjas identificadas · {{ money(preview.totals.unassigned_base) }} pendientes de granja.</p><p>Se guardarán el PDF original y los gastos por granja. El lote se propondrá por fecha de factura cuando exista un ciclo para esa fecha.</p><p v-if="dialogError" role="alert" class="notice error-notice">{{ dialogError }}</p><div class="actions"><button class="button primary" :disabled="busy||!preview.ready" @click="commit">{{ busy?'Importando…':'Importar costes' }}</button></div></FormDialog>
 <FormDialog v-if="edit" title="Detalle y asignación del gasto" :busy="busy" @close="edit=null">
  <p><strong>{{ edit.reference }}</strong> · {{ date(edit.invoice_date) }}<br>{{ edit.supplier_name }}</p><p>{{ edit.description }}<br><small>{{ edit.notes }}</small></p><p>{{ money(edit.base_amount) }} sin IVA · IVA {{ money(edit.vat_amount) }} · Total {{ money(edit.total_amount) }}</p><p class="muted">Albarán {{ edit.delivery_reference||'—' }} · página {{ edit.source_page }} · granja original {{ edit.source_farm_code||'sin indicar' }}<br>Unidades {{ farmQuantity(edit.quantity) }} · Precio {{ edit.unit_price??'—' }} · Importe original {{ edit.source_amount }}</p>
  <form class="farm-edit-form" @submit.prevent="saveCost">
